after:
    

    .amt-wrapper{
        max-width:1320px;
        margin:0 auto;
        padding:70px 20px;
    }

    .section-title{
        font-size:46px;
        font-weight:700;
        margin-bottom:50px;
        color:#111;
        letter-spacing:-0.5px;
    }

    .amt-grid{
        display:grid;
        grid-template-columns:repeat(2,1fr);
        gap:24px;
    }

    .amt-card{
        background:#fff;
        border-radius:28px;
        padding:40px;
        box-shadow:0 6px 22px rgba(0,0,0,0.06);
        transition:0.25s ease;
        border:1px solid #f1f1f1;
    }

    .amt-card:hover{
        transform:translateY(-5px);
        box-shadow:0 14px 36px rgba(0,0,0,0.10);
    }

    .amt-card.large{
        grid-column:span 2;
    }

    .amt-card h2{
        font-size:32px;
        margin:0 0 18px 0;
        color:#111;
    }

    .amt-card h3{
        font-size:24px;
        margin:0 0 14px 0;
        color:#111;
    }

    .amt-card p{
        font-size:16px;
        color:#555;
        margin-bottom:14px;
    }

    .amt-card a{
        color:#ff6b00;
        font-weight:600;
        text-decoration:none;
    }

    .amt-card a:hover{
        text-decoration:underline;
    }

    .highlight{
        color:#111;
        font-weight:700;
    }

    /* инфографика */
    .feature-grid{
        display:grid;
        grid-template-columns:repeat(2,1fr);
        gap:14px;
        margin-top:20px;
    }

    .feature-item{
        background:#fafafa;
        border:1px solid #ededed;
        border-radius:18px;
        padding:18px 18px;
        font-size:15px;
        color:#333;
        position:relative;
        overflow:hidden;
    }

    /* мягкий оранжевый акцент */
    .feature-item:before{
        content:"";
        position:absolute;
        left:0;
        top:0;
        width:4px;
        height:100%;
        background:#ff6b00;
        opacity:0.9;
    }

    img{
        width:100%;
        border-radius:18px;
        margin:18px 0;
        object-fit:cover;
    }

    /* адаптив */
    @media(max-width:992px){
        .amt-grid{grid-template-columns:1fr;}
        .amt-card.large{grid-column:span 1;}
        .feature-grid{grid-template-columns:1fr;}
    }

    @media(max-width:768px){
        .amt-wrapper{padding:40px 16px;}
        .section-title{font-size:34px;}
        .amt-card{padding:26px;}
        .amt-card h2{font-size:26px;}
    }



